def plus_eins(func):
    def wrapper(x):
        return func(x) + 1
    return wrapper

@plus_eins
def verdopple(x):
    return x * 2

print(verdopple(3))

def log(func):
    def wrapper():
        print("Aufruf")
        return func()
    return wrapper

@log
def hoch(a, b):
    return a ** b

print(hoch(2, 3))
